## 2. VECTOR SEARCH LATENCY

### Performance Budget
- **Target:** < 5ms for 10K vectors, < 20ms for 100K vectors
- **Current:** SQLite-vss fallback (inconsistent, 50-200ms)

### Vector Store Comparison

| Store | 10K Search | 100K Search | Memory | Persistence |
|-------|------------|-------------|--------|-------------|
| In-memory (current) | 0.1ms | 5ms | 80MB | No |
| SQLite-vss | 10-50ms | 100-200ms | 120MB | Yes |
| **LanceDB** | **2-5ms** | **8-15ms** | 150MB | Yes |
| **Chroma** | 3-8ms | 15-30ms | 180MB | Yes |
| pgvector | 5-15ms | 20-50ms | 200MB+ | Yes |

### Recommendation: LanceDB + HNSW Index

```typescript
// src/vector-store-lancedb.ts
import lancedb from '@lancedb/lancedb';

class LanceVectorStore {
  private db: lancedb.Connection;
  private table: lancedb.Table;

  async initialize() {
    this.db = await lancedb.connect('./data/vectors');

    // HNSW index: O(log n) search
    this.table = await this.db.createTable('knowledge', {
      schema: {
        id: 'string',
        url: 'string',
        content: 'string',
        embedding: { type: 'float[]', dimension: 384 }, // MiniLM
        metadata: 'string',
        timestamp: 'int64'
      },
      index: {
        type: 'hnsw',
        column: 'embedding',
        metric: 'cosine',
        M: 16,        // Connections per node
        ef_construction: 128  // Search depth during indexing
      }
    });
  }

  async search(queryEmbedding: Float32Array, limit = 10) {
    const results = await this.table
      .vectorSearch(queryEmbedding)
      .limit(limit)
      .select(['id', 'url', 'content', 'metadata'])
      .toArray();

    return results.map(r => ({
      ...r,
      score: 1 - r._distance  // Convert distance to similarity
    }));
  }
}
```

### Optimization: Hybrid Search

```typescript
// Combine vector similarity + keyword match
async hybridSearch(query: string, embedding: Float32Array, limit = 10) {
  const [vectorResults, keywordResults] = await Promise.all([
    this.vectorSearch(embedding, limit * 2),
    this.keywordSearch(query, limit * 2)  // FTS5 for keywords
  ]);

  // Reciprocal Rank Fusion (RRF)
  return this.rrfMerge(vectorResults, keywordResults, limit);
}

private rrfMerge(
  vectorResults: SearchResult[], 
  keywordResults: SearchResult[],
  k = 10
): SearchResult[] {
  const scores = new Map<string, number>();
  const results = new Map<string, SearchResult>();

  vectorResults.forEach((r, i) => {
    const score = 1 / (k + i + 1);  // RRF formula
    scores.set(r.id, (scores.get(r.id) || 0) + score);
    results.set(r.id, r);
  });

  keywordResults.forEach((r, i) => {
    const score = 1 / (k + i + 1);
    scores.set(r.id, (scores.get(r.id) || 0) + score);
    results.set(r.id, r);
  });

  return Array.from(scores.entries())
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit)
    .map(([id]) => results.get(id)!);
}
```

