## 4. CPU USAGE

### Performance Budget
- **Target:** < 30% CPU during normal operation, < 70% during burst
- **Current:** Unknown (Python process overhead)

### CPU Profiling Strategy

```typescript
// src/profiler.ts
class PerformanceProfiler {
  private metrics: Map<string, PerformanceMetrics> = new Map();

  async trackOperation<T>(name: string, operation: () => Promise<T>): Promise<T> {
    const start = process.hrtime.bigint();
    const cpuStart = process.cpuUsage();

    try {
      return await operation();
    } finally {
      const duration = Number(process.hrtime.bigint() - start) / 1e6;
      const cpuUsage = process.cpuUsage(cpuStart);

      this.recordMetric(name, {
        duration,
        userCpu: cpuUsage.user / 1000,  // ms
        systemCpu: cpuUsage.system / 1000,
        memoryDelta: process.memoryUsage().heapUsed
      });
    }
  }
}
```

### Optimization: Adaptive Throttling

```typescript
// src/throttler.ts
class AdaptiveThrottler {
  private loadMonitor: LoadMonitor;

  async throttleIfNeeded<T>(operation: () => Promise<T>): Promise<T> {
    const load = this.loadMonitor.getCpuLoad();

    if (load > 0.7) {
      // High load: defer to next tick, yield to event loop
      await new Promise(resolve => setImmediate(resolve));
    }

    if (load > 0.85) {
      // Critical load: queue operation
      return this.queueOperation(operation);
    }

    return operation();
  }
}
```

