## 5. THROUGHPUT

### Performance Budget
- **Target:** 20+ queries/second sustained, 50+ burst
- **Current:** Limited by Python IPC overhead

### Throughput Optimization: Request Batching

```typescript
// src/batch-processor.ts
class BatchProcessor<TInput, TOutput> {
  private batch: Array<{
    input: TInput;
    resolve: (output: TOutput) => void;
    reject: (error: Error) => void;
  }> = [];

  private batchTimer: NodeJS.Timeout | null = null;
  private readonly MAX_BATCH_SIZE = 64;
  private readonly MAX_WAIT_MS = 25;

  constructor(
    private processFn: (batch: TInput[]) => Promise<TOutput[]>
  ) {}

  async process(input: TInput): Promise<TOutput> {
    return new Promise((resolve, reject) => {
      this.batch.push({ input, resolve, reject });

      if (this.batch.length >= this.MAX_BATCH_SIZE) {
        this.flush();
      } else if (!this.batchTimer) {
        this.batchTimer = setTimeout(() => this.flush(), this.MAX_WAIT_MS);
      }
    });
  }

  private async flush() {
    if (this.batchTimer) {
      clearTimeout(this.batchTimer);
      this.batchTimer = null;
    }

    if (this.batch.length === 0) return;

    const currentBatch = this.batch.splice(0, this.MAX_BATCH_SIZE);

    try {
      const inputs = currentBatch.map(b => b.input);
      const outputs = await this.processFn(inputs);

      currentBatch.forEach((item, i) => {
        item.resolve(outputs[i]);
      });
    } catch (error) {
      currentBatch.forEach(item => {
        item.reject(error as Error);
      });
    }
  }
}
```

### Throughput: Connection Pooling

```typescript
// src/connection-pool.ts
class EmbeddingConnectionPool {
  private connections: EmbeddingConnection[] = [];
  private available: EmbeddingConnection[] = [];

  constructor(
    private connectionFactory: () => EmbeddingConnection,
    private poolSize = 4
  ) {
    // Pre-warm connections
    for (let i = 0; i < poolSize; i++) {
      const conn = connectionFactory();
      this.connections.push(conn);
      this.available.push(conn);
    }
  }

  async withConnection<T>(fn: (conn: EmbeddingConnection) => Promise<T>): Promise<T> {
    const conn = await this.acquire();
    try {
      return await fn(conn);
    } finally {
      this.release(conn);
    }
  }

  private async acquire(): Promise<EmbeddingConnection> {
    if (this.available.length > 0) {
      return this.available.pop()!;
    }

    // Wait for connection to become available
    return new Promise(resolve => {
      const check = () => {
        if (this.available.length > 0) {
          resolve(this.available.pop()!);
        } else {
          setTimeout(check, 10);
        }
      };
      check();
    });
  }
}
```

