## 3. Component Implementation Details

### 3.1 Embedding Engine (`src/core/embedding-engine.ts`)
```typescript
import { pipeline } from '@xenova/transformers';
import { EmbeddingEngine, EmbeddingConfig } from './types';

export class ONNXEmbeddingEngine implements EmbeddingEngine {
  private extractor: any;
  private config: EmbeddingConfig;

  constructor(config: EmbeddingConfig = { 
    model: 'Xenova/all-MiniLM-L6-v2',
    dimensions: 384 
  }) {
    this.config = config;
  }

  async initialize(): Promise<void> {
    // Lazy load model on first use
    if (!this.extractor) {
      this.extractor = await pipeline(
        'feature-extraction', 
        this.config.model,
        { 
          quantized: true,
          dtype: 'fp32' // Optimal for OpenVINO
        }
      );
    }
  }

  async embed(texts: string[]): Promise<Float32Array[]> {
    if (!this.extractor) await this.initialize();

    const embeddings: Float32Array[] = [];

    for (const text of texts) {
      const result = await this.extractor(text, { 
        pooling: 'mean',
        normalize: true 
      });
      embeddings.push(result.data);
    }

    return embeddings;
  }

  async embedQuery(query: string): Promise<Float32Array> {
    const [embedding] = await this.embed([query]);
    return embedding;
  }
}
```

### 3.2 Vector Store (`src/core/vector-store.ts`)
```typescript
import Database from 'better-sqlite3';
import { VectorStore, SearchResult, CacheEntry } from './types';

export class SQLiteVectorStore implements VectorStore {
  private db: Database.Database;

  constructor(dbPath: string = './rag-cache.db') {
    this.db = new Database(dbPath);
    this.initialize();
  }

  private initialize(): void {
    // Enable WAL mode for concurrent reads
    this.db.pragma('journal_mode = WAL');

    // Create tables with FTS5 for hybrid search
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS cache_entries (
        id TEXT PRIMARY KEY,
        url TEXT NOT NULL,
        content_hash TEXT NOT NULL,
        embedding BLOB NOT NULL,
        metadata TEXT,
        created_at INTEGER DEFAULT (unixepoch()),
        updated_at INTEGER DEFAULT (unixepoch()),
        access_count INTEGER DEFAULT 0,
        last_accessed INTEGER DEFAULT (unixepoch())
      );

      CREATE TABLE IF NOT EXISTS chunks (
        id TEXT PRIMARY KEY,
        entry_id TEXT,
        content TEXT NOT NULL,
        chunk_index INTEGER,
        metadata TEXT,
        FOREIGN KEY (entry_id) REFERENCES cache_entries(id)
      );

      CREATE VIRTUAL TABLE IF NOT EXISTS cache_fts USING fts5(
        content,
        content='chunks',
        content_rowid='rowid'
      );

      CREATE INDEX idx_entries_url ON cache_entries(url);
      CREATE INDEX idx_entries_hash ON cache_entries(content_hash);
    `);
  }

  async search(
    embedding: Float32Array, 
    topK: number = 10,
    threshold: number = 0.6
  ): Promise<SearchResult[]> {
    // Convert Float32Array to Buffer for SQLite
    const embeddingBuffer = Buffer.from(embedding.buffer);

    const results = this.db.prepare(`
      SELECT 
        id, url, metadata, access_count,
        similarity(embedding, ?) as score
      FROM cache_entries
      WHERE similarity(embedding, ?) > ?
      ORDER BY score DESC
      LIMIT ?
    `).all(embeddingBuffer, embeddingBuffer, threshold, topK) as any[];

    return results.map(result => ({
      entryId: result.id,
      url: result.url,
      score: result.score,
      metadata: JSON.parse(result.metadata || '{}'),
      accessCount: result.access_count
    }));
  }

  async addEntry(entry: CacheEntry): Promise<void> {
    const embeddingBuffer = Buffer.from(entry.embedding.buffer);

    this.db.prepare(`
      INSERT OR REPLACE INTO cache_entries 
      (id, url, content_hash, embedding, metadata, access_count)
      VALUES (?, ?, ?, ?, ?, ?)
    `).run(
      entry.id,
      entry.url,
      entry.contentHash,
      embeddingBuffer,
      JSON.stringify(entry.metadata),
      0
    );

    // Store chunks for FTS
    if (entry.chunks) {
      const insertChunk = this.db.prepare(`
        INSERT INTO chunks (id, entry_id, content, chunk_index, metadata)
        VALUES (?, ?, ?, ?, ?)
      `);

      const insertMany = this.db.transaction((chunks: any[]) => {
        for (const chunk of chunks) {
          insertChunk.run(
            `${entry.id}-${chunk.index}`,
            entry.id,
            chunk.content,
            chunk.index,
            JSON.stringify(chunk.metadata)
          );
        }
      });

      insertMany(entry.chunks);

      // Update FTS index
      this.db.prepare(`
        INSERT INTO cache_fts(rowid, content)
        SELECT rowid, content FROM chunks 
        WHERE entry_id = ?
      `).run(entry.id);
    }
  }

  async updateAccessCount(entryId: string): Promise<void> {
    this.db.prepare(`
      UPDATE cache_entries 
      SET access_count = access_count + 1,
          last_accessed = unixepoch()
      WHERE id = ?
    `).run(entryId);
  }

  async getEntry(entryId: string): Promise<CacheEntry | null> {
    const entry = this.db.prepare(`
      SELECT * FROM cache_entries WHERE id = ?
    `).get(entryId) as any;

    if (!entry) return null;

    const chunks = this.db.prepare(`
      SELECT * FROM chunks 
      WHERE entry_id = ? 
      ORDER BY chunk_index
    `).all(entryId) as any[];

    return {
      id: entry.id,
      url: entry.url,
      contentHash: entry.content_hash,
      embedding: new Float32Array(entry.embedding.buffer),
      metadata: JSON.parse(entry.metadata || '{}'),
      chunks: chunks.map(c => ({
        index: c.chunk_index,
        content: c.content,
        metadata: JSON.parse(c.metadata || '{}')
      })),
      accessCount: entry.access_count
    };
  }

  async deleteEntry(entryId: string): Promise<void> {
    this.db.prepare('DELETE FROM chunks WHERE entry_id = ?').run(entryId);
    this.db.prepare('DELETE FROM cache_entries WHERE id = ?').run(entryId);
    this.db.prepare('DELETE FROM cache_fts WHERE rowid IN (SELECT rowid FROM chunks WHERE entry_id = ?)').run(entryId);
  }

  async getStats(): Promise<{
    totalEntries: number;
    totalChunks: number;
    avgAccessCount: number;
  }> {
    const stats = this.db.prepare(`
      SELECT 
        COUNT(DISTINCT id) as total_entries,
        COUNT(DISTINCT chunk_id) as total_chunks,
        AVG(access_count) as avg_access
      FROM cache_entries
      JOIN chunks ON chunks.entry_id = cache_entries.id
    `).get() as any;

    return {
      totalEntries: stats.total_entries,
      totalChunks: stats.total_chunks,
      avgAccessCount: stats.avg_access || 0
    };
  }
}
```

### 3.3 Cache Manager (`src/core/cache-manager.ts`)
```typescript
import { v4 as uuid } from 'uuid';
import { ONNXEmbeddingEngine } from './embedding-engine';
import { SQLiteVectorStore } from './vector-store';
import { ContentProcessor } from '../services/content-processor';
import { CacheManager, CacheConfig, CacheEntry, SearchResult } from './types';

export class RAGCacheManager implements CacheManager {
  private embeddingEngine: ONNXEmbeddingEngine;
  private vectorStore: SQLiteVectorStore;
  private contentProcessor: ContentProcessor;
  private config: CacheConfig;

  constructor(config: CacheConfig = {}) {
    this.config = {
      similarityThreshold: 0.7,
      maxChunksPerEntry: 10,
      chunkSize: 500,
      chunkOverlap: 50,
      cacheExpiry: 30 * 24 * 60 * 60, // 30 days
      ...config
    };

    this.embeddingEngine = new ONNXEmbeddingEngine();
    this.vectorStore = new SQLiteVectorStore(config.dbPath);
    this.contentProcessor = new ContentProcessor(this.config);
  }

  async initialize(): Promise<void> {
    await this.embeddingEngine.initialize();
    console.log('RAG Cache Manager initialized');
  }

  async cacheContent(
    url: string, 
    content: string, 
    metadata: Record<string, any> = {}
  ): Promise<string> {
    // Check if content already cached
    const existingEntry = await this.findExistingEntry(url, content);
    if (existingEntry) {
      await this.vectorStore.updateAccessCount(existingEntry.id);
      return existingEntry.id;
    }

    // Process and chunk content
    const chunks = this.contentProcessor.processContent(content, url, metadata);

    // Generate embeddings for all chunks
    const chunkTexts = chunks.map(c => c.content);
    const embeddings = await this.embeddingEngine.embed(chunkTexts);

    // Create entry embedding (average of chunk embeddings)
    const entryEmbedding = this.averageEmbeddings(embeddings);

    // Create cache entry
    const entryId = uuid();
    const contentHash = this.hashContent(content);

    const cacheEntry: CacheEntry = {
      id: entryId,
      url,
      contentHash,
      embedding: entryEmbedding,
      metadata: {
        ...metadata,
        cachedAt: Date.now(),
        chunkCount: chunks.length
      },
      chunks: chunks.map((chunk, i) => ({
        index: i,
        content: chunk.content,
        embedding: embeddings[i],
        metadata: chunk.metadata
      })),
      accessCount: 0
    };

    await this.vectorStore.addEntry(cacheEntry);
    return entryId;
  }

  async queryKnowledge(
    query: string, 
    options: {
      topK?: number;
      threshold?: number;
      includeChunks?: boolean;
    } = {}
  ): Promise<SearchResult[]> {
    const { topK = 5, threshold = this.config.similarityThreshold, includeChunks = true } = options;

    // Embed query
    const queryEmbedding = await this.embeddingEngine.embedQuery(query);

    // Search vector store
    let results = await this.vectorStore.search(queryEmbedding, topK * 2, threshold);

    // Rerank with hybrid search (semantic + keyword)
    if (includeChunks) {
      results = await this.enhanceResultsWithChunks(results, query, topK);
    }

    return results.slice(0, topK);
  }

  async enhanceResultsWithChunks(
    results: SearchResult[], 
    query: string, 
    topK: number
  ): Promise<SearchResult[]> {
    const enhanced: SearchResult[] = [];

    for (const result of results) {
      const entry = await this.vectorStore.getEntry(result.entryId);
      if (!entry) continue;

      // Score each chunk against query
      const chunkScores = await Promise.all(
        entry.chunks.map(async chunk => {
          const chunkEmbedding = chunk.embedding;
          const queryEmbedding = await this.embeddingEngine.embedQuery(query);
          const semanticScore = this.cosineSimilarity(queryEmbedding, chunkEmbedding);
          const keywordScore = this.keywordOverlapScore(query, chunk.content);

          return {
            chunk,
            score: semanticScore * 0.7 + keywordScore * 0.3
          };
        })
      );

      // Sort chunks by score
      const sortedChunks = chunkScores
        .sort((a, b) => b.score - a.score)
        .slice(0, 3);

      enhanced.push({
        ...result,
        chunks: sortedChunks.map(sc => sc.chunk),
        relevanceScore: sortedChunks[0]?.score || result.score
      });

      await this.vectorStore.updateAccessCount(result.entryId);
    }

    return enhanced.sort((a, b) => b.relevanceScore - a.relevanceScore).slice(0, topK);
  }

  private async findExistingEntry(url: string, content: string): Promise<CacheEntry | null> {
    const contentHash = this.hashContent(content);

    // Check by URL first (exact match)
    const urlMatch = await this.vectorStore.searchByUrl(url);
    if (urlMatch && urlMatch.contentHash === contentHash) {
      return urlMatch;
    }

    // Check by content hash (duplicate content, different URLs)
    const hashMatch = await this.vectorStore.searchByHash(contentHash);
    if (hashMatch) {
      return hashMatch;
    }

    return null;
  }

  private averageEmbeddings(embeddings: Float32Array[]): Float32Array {
    const dims = embeddings[0].length;
    const avg = new Float32Array(dims);

    for (const emb of embeddings) {
      for (let i = 0; i < dims; i++) {
        avg[i] += emb[i];
      }
    }

    for (let i = 0; i < dims; i++) {
      avg[i] /= embeddings.length;
    }

    return avg;
  }

  private hashContent(content: string): string {
    const crypto = require('crypto');
    return crypto.createHash('sha256').update(content).digest('hex');
  }

  private cosineSimilarity(a: Float32Array, b: Float32Array): number {
    let dotProduct = 0;
    let normA = 0;
    let normB = 0;

    for (let i = 0; i < a.length; i++) {
      dotProduct += a[i] * b[i];
      normA += a[i] * a[i];
      normB += b[i] * b[i];
    }

    return dotProduct / (Math.sqrt(normA) * Math.sqrt(normB));
  }

  private keywordOverlapScore(query: string, content: string): number {
    const queryWords = new Set(query.toLowerCase().split(/\W+/));
    const contentWords = new Set(content.toLowerCase().split(/\W+/));

    let overlap = 0;
    for (const word of queryWords) {
      if (contentWords.has(word)) overlap++;
    }

    return overlap / queryWords.size;
  }
}
