### Credit Reduction Strategy
```typescript
// src/services/query-processor.ts
export class QueryProcessor {
  async shouldCallFirecrawl(
    query: string, 
    cacheResults: SearchResult[]
  ): Promise<{ 
    shouldCall: boolean;
    confidence: number;
    reason: string;
  }> {
    if (cacheResults.length === 0) {
      return { shouldCall: true, confidence: 1, reason: 'no-cache' };
    }

    const topScore = cacheResults[0].score;
    const accessCount = cacheResults[0].accessCount;

    // High confidence match
    if (topScore > 0.85) {
      return { 
        shouldCall: false, 
        confidence: topScore,
        reason: `high-confidence-match(${topScore.toFixed(2)})`
      };
    }

    // Medium confidence with recent access
    if (topScore > 0.7 && accessCount > 3) {
      return {
        shouldCall: false,
        confidence: topScore,
        reason: `repeated-access(${accessCount}x)`
      };
    }

    // Low confidence or stale
    return {
      shouldCall: true,
      confidence: topScore,
      reason: `low-confidence(${topScore.toFixed(2)})`
    };
  }
}
