  // Tier 1: Page-level candidate selection
  TIER1_CANDIDATE_CUTOFF: 0.65,     // MiniLM cosine similarity
  TIER1_MAX_CANDIDATES: 50,         // Cap to prevent scan

  // Tier 2: Chunk-level semantic match
