## 5. Update Strategy

### Three-tier freshness system:

```
┌────────────────────────────────────────────────────────────────┐
│                    CACHE FRESHNESS MODEL                       │
├────────────────────────────────────────────────────────────────┤
│                                                                │
│  IMMUTABLE (never re-scrape)                                   │
│  ├── API documentation snapshots (versioned URLs)              │
│  ├── Archived blog posts (publication date > 6 months)         │
│  └── Content with stable_hash == previous hash                 │
│                                                                │
│  REFRESH_ON_ACCESS (lazy re-validation)                        │
│  ├── Active documentation (updated frequently)                 │
│  ├── Content accessed > 7 days ago                             │
│  └── Content where query scored 0.78-0.85 (marginal match)     │
│                                                                │
│  ALWAYS_FRESH (periodic re-scrape)                             │
│  ├── Dynamic content (forums, changelogs)                      │
│  ├── Content with changing_hash                                │
│  └── Top-10 most accessed URLs (re-scrape daily)               │
│                                                                │
└────────────────────────────────────────────────────────────────┘
```

### Implementation:

```typescript
// src/cache-manager.ts

interface CacheEntry {
  url: string;
  scrapedAt: number;
  contentHash: string;           // SHA-256 of raw content
  contentCategory: 'immutable' | 'refresh-on-access' | 'always-fresh';

  // Staleness tracking
  lastRevalidated: number;
  revalidationCount: number;
  revalidationCost: number;      // Credits spent on re-validation

  // Usage-based freshness
  accessCount: number;
  avgQueryScore: number;         // If trending down, content may be stale
  lastAccessedAt: number;
}

class CacheManager {

  async shouldRefresh(entry: CacheEntry): Promise<{
    refresh: boolean;
    reason: string;
    estimatedCost: number;
  }> {
    const now = Date.now();
    const ageDays = (now - entry.scrapedAt) / (1000 * 60 * 60 * 24);

    // Rule 1: Content category
    if (entry.contentCategory === 'immutable' && ageDays < 365) {
      return { refresh: false, reason: 'immutable_fresh', estimatedCost: 0 };
    }

    // Rule 2: Always-fresh window
    if (entry.contentCategory === 'always-fresh') {
      const revalidationInterval = entry.accessCount > 100 ? 1 : 7; // days
      if (ageDays > revalidationInterval) {
        return { 
          refresh: true, 
          reason: 'periodic_fresh',
          estimatedCost: 0.81  // Full scrape cost
        };
      }
    }

    // Rule 3: Access-triggered refresh
    if (entry.contentCategory === 'refresh-on-access') {
      const daysSinceAccess = (now - entry.lastAccessedAt) / (1000 * 60 * 60 * 24);
      if (daysSinceAccess > 7 && entry.accessCount > 5) {
        return { 
          refresh: true, 
          reason: 'stale_on_access',
          estimatedCost: 0.81 
        };
      }
    }

    // Rule 4: Score degradation signal
    if (entry.avgQueryScore < 0.70 && entry.accessCount > 20) {
      // If the content is getting worse matches, the world may have changed
      return {
        refresh: true,
        reason: 'score_degradation',
        estimatedCost: 0.81
      };
    }

    return { refresh: false, reason: 'fresh', estimatedCost: 0 };
  }

  async revalidate(entry: CacheEntry, query: string): Promise<boolean> {
    // CHEAP revalidation: fetch headers + compare hashes
    // Instead of full re-scrape, do a conditional GET
    const response = await fetch(entry.url, {
      method: 'HEAD',
      headers: { 'If-None-Match': entry.etag }
    });

    if (response.status === 304) {
      // Not modified - update timestamp, no credits spent
      entry.lastRevalidated = Date.now();
      return true;  // Still fresh
    }

    // Content changed - full re-scrape needed
    return false;
  }
}
```

### Credit Savings Model:

```
Scenario: 100 queries/day hitting cache

WITHOUT cache:
  100 queries × 0.81 credits = 81 credits/day

WITH cache (at 60% hit rate after warm-up):
  40 cache misses × 0.81 = 32.4 credits (new scrapes)
  60 cache hits × 0.00  = 0 credits (retrieval only)

  + Revalidation overhead:
    10% of hits trigger header check (0 credits)
    5% of hits trigger full re-scrape = 3 × 0.81 = 2.43

  TOTAL: 32.4 + 2.43 = 34.83 credits/day
  SAVINGS: 57% reduction (target: 63%)

  To reach 0.30 target: need 70% hit rate
  30 misses × 0.81 = 24.3
  + revalidation: 3 × 0.81 = 2.43
  TOTAL: 26.73 credits for 100 queries = 0.27/query ✓
```

